import math
from math import comb

def prob_at_least_two(n, d=365):
    p_no_pair = 1.0
    for k in range(n):
        p_no_pair *= (d - k) / d
    return 1 - p_no_pair

def prob_no_triple(n, d=365):
    # Count number of ways to assign n people to d birthdays with max 2 per birthday
    # State: dp[i][j][k] = ways using i birthdays, with j birthdays having 1 person, k birthdays having 2 people
    # and the rest (i - j - k) birthdays empty
    # We want dp[d][j][k] where j + 2*k = n
    dp = [[[0]*(n//2+2) for _ in range(n+2)] for __ in range(d+1)]
    dp[0][0][0] = 1
    for i in range(1, d+1):
        for j in range(n+1):
            for k in range(n//2+1):
                val = dp[i-1][j][k]
                if val == 0:
                    continue
                # Assign 0 person to this birthday
                dp[i][j][k] += val
                # Assign 1 person to this birthday if possible
                if j+1 <= n and j+1+2*k <= n:
                    dp[i][j+1][k] += val
                # Assign 2 persons to this birthday if possible
                if k+1 <= n//2 and j+2*k+2 <= n:
                    dp[i][j][k+1] += val
    total_ways = d**n
    ways_no_triple = 0
    for j in range(n+1):
        for k in range(n//2+1):
            if j + 2*k == n:
                ways_no_triple += dp[d][j][k] * math.factorial(n) // (math.factorial(j) * (2**k) * math.factorial(k))
    return ways_no_triple / total_ways

